package com.kkirikkiri.calendar.crawler;

import java.nio.file.*;
import java.util.*;
import tools.jackson.databind.JsonNode;
import static com.kkirikkiri.calendar.crawler.CalendarMultiSupport.*;

/** Selected existing cases plus missing HTTP contracts; crawler uses loopback HTML only. */
public class CalendarHttp5 extends CalendarMultiInstance {
    static final int PORT=18096;
    static final List<String> REUSED=List.of("http-cross-server-crud","http-private-ownership","http-system-category-protection");
    static final List<String> ADDED=List.of("category-read-patch-delete", "foreign-category-mutations", "collected-event-protection", "public-private-visibility", "period-overlap-category-filter", "local-crawl-public-admin-link", "create-date-time-boundaries", "patch-null-merge", "patch-merged-range-rollback", "patch-description-empty", "category-null-merge", "query-date-boundaries");
    public static void main(String[] args)throws Exception {
        if(args.length==1&&args[0].equals("--list")){System.out.println(JSON.writeValueAsString(java.util.stream.Stream.concat(REUSED.stream(),ADDED.stream()).toList()));return;}
        check("true".equals(System.getenv("MC5_APPROVED")),"Explicit approved isolated execution required");
        root=Path.of(args[0]).toRealPath();out=Path.of(args[1]).toRealPath();String priority=args[2];check(Set.of("P0","P1").contains(priority),"Unknown priority");boolean recovery="true".equals(System.getenv("MC5_PATCH_NULL_RECOVERY"));check(!recovery||priority.equals("P1"),"Recovery priority mismatch");boolean complete=false,cleaned=false;
        try {
            try(var c=open()){
                grants(c);tables=rows(c,"SELECT table_name FROM information_schema.tables WHERE table_schema=DATABASE() ORDER BY table_name").stream().map(x->x.values().iterator().next().toString()).toList();
                check(tables.size()==31,"Expected initialized schema");for(var t:tables)check(number(c,"SELECT COUNT(*) FROM `"+t+"`")==0,"Previous phase did not clean fixtures");originalDdl=ddl(c);
                write(out.resolve("environment.json"),rows(c,"SELECT DATABASE() db,CURRENT_USER() account,VERSION() version,@@server_uuid uuid,@@hostname host,@@session.time_zone zone"));write(out.resolve("schema-before.json"),originalDdl);
            }
            a=start(PORT,"Asia/Seoul","UTC");b=a;
            // Existing assertions are reused on one server. This run makes no cross-JVM claim.
            if(recovery)selected=Set.of("patch-null-merge");else if(priority.equals("P0")){selected=new HashSet<>(REUSED);run();selected.addAll(ADDED.subList(0,6));}else selected=new HashSet<>(ADDED.subList(6,12));additional();complete=true;
        }catch(Throwable t){cases.add(Map.of("name","harness","status","INCOMPLETE","error",error(t)));}
        finally {
            for(var s:servers)try{s.stop();}catch(Throwable t){events.add(Map.of("kind","stopFailure","error",error(t)));}HTTP.close();
            boolean stopped=servers.stream().noneMatch(s->s.process.isAlive());
            if(stopped)try{cleanup();cleaned=true;}catch(Throwable t){events.add(Map.of("kind","cleanupFailure","error",error(t)));}
            write(out.resolve("cases.json"),cases);write(out.resolve("requests.json"),requests);write(out.resolve("servers.json"),events);
            boolean pass=complete&&cleaned&&stopped&&cases.size()==(recovery?1:priority.equals("P0")?9:6)&&cases.stream().allMatch(c->"PASS".equals(c.get("status")))&&events.stream().noneMatch(e->"forbiddenExternalCall".equals(e.get("kind")));
            var summary=new LinkedHashMap<String,Object>();summary.put("priority",priority);summary.put("verdict",pass?"PASS":"FAIL_OR_INCOMPLETE");summary.put("scenarios",cases.size());summary.put("passed",cases.stream().filter(c->"PASS".equals(c.get("status"))).count());summary.put("httpRequests",requests.size());summary.put("serverHttpObserved",events.stream().filter(e->"http".equals(e.get("kind"))).count());summary.put("processesStopped",stopped);summary.put("allTablesEmpty",cleaned);summary.put("realSchoolCalls",0);summary.put("singleJvm",true);write(out.resolve("summary.json"),summary);if(!pass)System.exit(1);
        }
    }
    static Reply request(String method,String path,Object body,Member member)throws Exception{return api(PORT,method,path,body,member==null?null:member.token());}
    static JsonNode categories(Member member)throws Exception{var r=request("GET","/api/calendar/categories",null,member);expect(r,200,"");return r.data();}
    static JsonNode find(JsonNode values,long id){for(var v:values)if(v.path("id").asLong()==id)return v;throw new AssertionError("Expected ID missing");}
    static Set<Long> ids(JsonNode values){var set=new TreeSet<Long>();for(var v:values)set.add(v.path("id").asLong());return set;}
    static List<Map<String,Object>> snapshot()throws Exception{try(var c=open()){var all=new ArrayList<Map<String,Object>>();for(String t:List.of("calendar_event","calendar_category","calendar_category_setting"))all.addAll(rows(c,"SELECT * FROM "+t+" ORDER BY 1"));return all;}}
    static void collected()throws Exception{crawl(a);done(a);check(n("SELECT COUNT(*) FROM calendar_event WHERE source_type='CRAWLED'")==62,"Local HTML fixture count mismatch");}
    static void additional()throws Exception {
        test(ADDED.get(0),()->{
            long before=n("SELECT COUNT(*) FROM calendar_category_setting");var read=categories(me);check(find(read,personal).path("label").asString().equals("personal"),"Missing own category");check(n("SELECT COUNT(*) FROM calendar_category_setting")==before,"GET wrote settings");
            var r=request("PATCH","/api/calendar/categories/"+personal,Map.of("label","changed","color","#abcdef","enabled",false),me);expect(r,200,"");check(find(categories(me),personal).equals(r.data()),"Category PATCH read mismatch");
            r=request("DELETE","/api/calendar/categories/"+personal,null,me);expect(r,200,"");check(r.data().isNull()&&!ids(categories(me)).contains(personal)&&n("SELECT COUNT(*) FROM calendar_category_setting WHERE category_id=?",personal)==0,"Category delete incomplete");return Map.of("getReadOnly",true,"settingsDeleted",true);
        });
        test(ADDED.get(1),()->{long foreign=category(PORT,other,"foreign");var before=snapshot();for(String method:List.of("PATCH","DELETE"))expect(request(method,"/api/calendar/categories/"+foreign,method.equals("PATCH")?Map.of("label","stolen"):null,me),403,"FORBIDDEN");check(!ids(categories(me)).contains(foreign)&&before.equals(snapshot()),"Foreign category leaked/changed");return Map.of("blockedMutations",2);});
        test(ADDED.get(2),()->{collected();long id=n("SELECT MIN(event_id) FROM calendar_event");var before=snapshot();for(Member who:List.of(me,admin))for(String method:List.of("PATCH","DELETE"))expect(request(method,"/api/calendar/events/"+id,method.equals("PATCH")?Map.of("title","stolen"):null,who),403,"FORBIDDEN");check(before.equals(snapshot()),"Collected event changed");return Map.of("blockedMutations",4,"fixture","LOCAL_HTML_ONLY");});
        test(ADDED.get(3),()->{collected();long mine=create(PORT,me,personal,"private").data().path("id").asLong();long foreign=category(PORT,other,"other");long theirs=create(PORT,other,foreign,"other-private").data().path("id").asLong();
            for(Member who:Arrays.asList(null,me,other)){var r=request("GET",PUBLIC,null,who);expect(r,200,"");var found=ids(r.data());check(found.size()==(who==null?62:63),"Visibility count");check(found.contains(mine)==(who==me)&&found.contains(theirs)==(who==other),"Personal visibility leak");for(var v:r.data())check(v.path("editable").asBoolean()==(v.path("id").asLong()==mine&&who==me||v.path("id").asLong()==theirs&&who==other),"Editable flag mismatch");}return Map.of("public",62,"ownView",63,"fixture","LOCAL_HTML_ONLY");});
        test(ADDED.get(4),()->{var expected=new TreeSet<Long>();for(String[] dates:new String[][]{{"2026-10-15","2026-10-16"},{"2026-10-17","2026-10-18"},{"2026-10-14","2026-10-20"},{"2026-10-14","2026-10-15"},{"2026-10-19","2026-10-20"}}){var body=event(personal,"overlap");body.put("startDate",dates[0]);body.put("endDate",dates[1]);var r=request("POST","/api/calendar/events",body,me);expect(r,200,"");if(expected.size()<3)expected.add(r.data().path("id").asLong());}
            check(ids(list(PORT,me)).equals(expected),"Inclusive overlap mismatch");String code=find(categories(me),personal).path("code").asString();var r=request("GET",LIST+"&categories="+code,null,me);expect(r,200,"");check(ids(r.data()).equals(expected),"Category filter mismatch");r=request("GET",LIST+"&categories=SCHOOL",null,me);expect(r,200,"");check(r.data().isEmpty(),"Category filter ignored");return Map.of("inclusiveOverlaps",expected);});
        test(ADDED.get(5),()->{collected();var publicReply=request("GET",PUBLIC,null,null);expect(publicReply,200,"");var status=status(PORT);check(status.path("status").asString().equals("COMPLETED")&&status.path("recentCollectedCount").asLong()==62&&status.path("totalCollectedCount").asLong()==62&&publicReply.data().size()==62,"Public/admin/storage mismatch");crawl(a);done(a);check(status(PORT).path("recentCollectedCount").asLong()==0&&status(PORT).path("totalCollectedCount").asLong()==62,"Repeat local crawl duplicated rows");return Map.of("fixture","LOCAL_HTML_ONLY","realSchoolVerified",false,"stored",62,"public",62,"repeatNew",0);});
        test(ADDED.get(6),()->{int rejected=0;for(var pair:List.of(Map.of("startDate","2026-10-18","endDate","2026-10-16"),Map.of("startTime","24:00"),Map.of("startTime","9:00"),Map.of("startDate","2026-10-16","endDate","2026-10-16","startTime","10:00","endTime","10:00"))){var body=event(personal,"invalid");body.putAll(pair);expect(request("POST","/api/calendar/events",body,me),400,"VALIDATION_ERROR");rejected++;}check(n("SELECT COUNT(*) FROM calendar_event")==0,"Invalid create wrote data");var accepted=event(personal,"midnight");accepted.put("startTime","00:00");accepted.put("endTime","23:59");expect(request("POST","/api/calendar/events",accepted,me),200,"");return Map.of("rejected",rejected,"midnightAccepted",true);});
        test(ADDED.get(7),()->{var body=event(personal,"retained");body.put("description","keep");var r=request("POST","/api/calendar/events",body,me);expect(r,200,"");long id=r.data().path("id").asLong();var initial=r.data();var before=snapshot();var nulls=new LinkedHashMap<String,Object>();for(String k:List.of("title","startDate","endDate","startTime","endTime","categoryId","description"))nulls.put(k,null);for(var patch:List.of(Map.<String,Object>of(),nulls)){r=request("PATCH","/api/calendar/events/"+id,patch,me);expect(r,200,"");check(r.data().equals(initial)&&r.data().path("startTime").asString().equals("23:59")&&r.data().path("endTime").asString().equals("00:00"),"Null PATCH response changed fields or violated HH:mm contract");}check(before.equals(snapshot())&&find(list(PORT,me),id).equals(initial),"Null PATCH changed storage or GET response");return Map.of("omittedAndNullRetained",true,"startTime","23:59","endTime","00:00","descriptionPreserved",true,"allDtoFieldsPreserved",true,"dbSnapshotUnchanged",true);});
        test(ADDED.get(8),()->{var r=create(PORT,me,personal,"merged");expect(r,200,"");long id=r.data().path("id").asLong();var before=snapshot();for(var patch:List.of(Map.of("startDate","2026-10-18"),Map.of("endDate","2026-10-16"),Map.of("endTime","24:00"))){expect(request("PATCH","/api/calendar/events/"+id,patch,me),400,"VALIDATION_ERROR");check(before.equals(snapshot()),"Rejected merged PATCH changed rows");}return Map.of("rejected",3,"unchanged",true);});
        test(ADDED.get(9),()->{var body=event(personal,"description");body.put("description","keep");var r=request("POST","/api/calendar/events",body,me);expect(r,200,"");long id=r.data().path("id").asLong();r=request("PATCH","/api/calendar/events/"+id,Map.of("description",""),me);expect(r,200,"");check(find(list(PORT,me),id).path("description").asString().isEmpty(),"Empty description not saved");return Map.of("emptyDescriptionSaved",true);});
        test(ADDED.get(10),()->{var nulls=new LinkedHashMap<String,Object>();for(String key:List.of("label","color","enabled"))nulls.put(key,null);var before=snapshot();expect(request("PATCH","/api/calendar/categories/"+personal,nulls,me),200,"");check(before.equals(snapshot()),"Null category PATCH changed rows");return Map.of("retained",true);});
        test(ADDED.get(11),()->{for(String q:List.of("?from=2026-10-18&to=2026-10-16","?from=2026-10-16","?from=2026-02-30&to=2026-10-18"))expect(request("GET","/api/calendar/events"+q,null,me),400,"VALIDATION_ERROR");return Map.of("rejected",3);});
    }
}
